require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';Auth::requireRole('admin');$error=null;if(request_method('POST')){Csrf::verify();try{$pdo=db();$tables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);header('Content-Type: application/sql');header('Content-Disposition: attachment; filename="lifelink_sl_backup_'.date('Ymd_His').'.sql"');echo "-- LifeLink SL academic prototype SQL backup\nSET FOREIGN_KEY_CHECKS=0;\n\n";foreach($tables as $table){$safe='`'.str_replace('`','``',$table).'`';$create=$pdo->query("SHOW CREATE TABLE $safe")->fetch();echo "DROP TABLE IF EXISTS $safe;\n".$create['Create Table'].";\n\n";$rows=$pdo->query("SELECT * FROM $safe")->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $row){$cols=array_map(fn($c)=>'`'.str_replace('`','``',$c).'`',array_keys($row));$vals=array_map(fn($v)=>$v===null?'NULL':$pdo->quote((string)$v),array_values($row));echo 'INSERT INTO '.$safe.' ('.implode(',',$cols).') VALUES ('.implode(',',$vals).");\n";}echo "\n";}echo "SET FOREIGN_KEY_CHECKS=1;\n";audit('database_backup_created','system',null);exit;}catch(Throwable $e){$error=$e->getMessage();}}
